    marks=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v in (1,2,3,4)]
    r0=min(r for r,c in marks); r1=max(r for r,c in marks)
    c0=min(c for r,c in marks); c1=max(c for r,c in marks)
    key=[[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    cells=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8]
    a=min(r for r,c in cells); b=max(r for r,c in cells)
    x=min(c for r,c in cells); y=max(c for r,c in cells)
    sh=(b-a+1)//len(key); sw=(y-x+1)//len(key[0])
